(5782003,'Coloring Prism Pro','cash','Other','{"desc":"Double-click to dye a decoration item once. Select one color from the provided color series to adjust its hue, chroma, and brightness. If it is used multiple times, the item is dyed based on the original color of the target item. Can only be used on untradable items that are not time-restricted. Can''t be used on Rings, Pet Equipment, or items that can''t use Prisms. Special effects will not be dyed"}'::jsonb,'catalog','https://osmsdataexplorer.com/data/current/cash_shop.json',true),
(5782004,'Weapon Effect Prism','cash','Other','{"desc":"Double-click to dye a decoration weapon item''s effect once. The weapon''s dyes will be maintained upon use; only normal and special effects will be dyed. Select one color from the provided color series to adjust its hue, chroma, and brightness. If it is used multiple times, the item is dyed based on the original color of the target effect. Can only be used on untradable items that are not time-rest"}'::jsonb,'catalog','https://osmsdataexplorer.com/data/current/cash_shop.json',true)
